import{c as t,Q as o,j as a,m as i}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"How the Copilot Works","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/how-it-works.md","filePath":"copilot/how-it-works.md","lastUpdated":null}'),r={name:"copilot/how-it-works.md"};function n(s,e,l,c,d,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="how-the-copilot-works" tabindex="-1">How the Copilot Works <a class="header-anchor" href="#how-the-copilot-works" aria-label="Permalink to &quot;How the Copilot Works&quot;">​</a></h1><p>A request traverses four stages, each observable in code.</p><h2 id="_1-build-context" tabindex="-1">1. Build context <a class="header-anchor" href="#_1-build-context" aria-label="Permalink to &quot;1. Build context&quot;">​</a></h2><p><code>finsight-agent::context::build_context</code> queries your encrypted database and assembles:</p><ul><li><code>CashflowContext</code> — balances, recent income/expenses, run rate</li><li><code>BudgetContext</code> — this month’s envelopes, To Budget, carryover</li><li><code>GoalContextItem[]</code> — targets, progress, quick-fill eligibility</li><li><code>TransactionContext</code> — windowed actuals the question touches</li><li><code>MemoryItem[]</code> — stored, reviewable memories</li><li><code>WellnessContext</code> — emergency-fund months (+ reliability), snowball order, allocation, 10/20/30-year projection</li><li><code>CurrencyContext</code> — primary currency and explicitly unconverted holdings</li><li><code>InvestmentAccountContext[]</code> — positions only as imported; no price discovery</li></ul><p>The wellness block is the only place the six financial principles become numbers. Everything downstream reads that block.</p><h2 id="_2-build-the-system-prompt" tabindex="-1">2. Build the system prompt <a class="header-anchor" href="#_2-build-the-system-prompt" aria-label="Permalink to &quot;2. Build the system prompt&quot;">​</a></h2><p><code>planner.rs::build_system_prompt</code> embeds:</p><ul><li>The <strong>Financial Freedom Framework</strong> verbatim (Pay Yourself First, Conscious Spending, Emergency Fund, Debt Snowball, Compound Growth, Behaviour over math, Journey).</li><li>Tool allow-list (<code>ACTION_KINDS</code>), navigation guardrails, and the “do not invent totals when unconverted holdings exist” rule.</li><li>Provider and model identity for disclosure.</li></ul><h2 id="_3-call-the-provider" tabindex="-1">3. Call the provider <a class="header-anchor" href="#_3-call-the-provider" aria-label="Permalink to &quot;3. Call the provider&quot;">​</a></h2><p><code>CompletionProvider</code> trait (<code>crates/finsight-agent/src/providers</code>) abstracts Ollama, OpenAI-compatible, and Anthropic over HTTP. The request sends the system prompt + context + user question. Streaming responses flow back as reasoning deltas, tool-call parts, and text.</p><p>Provider keys live per-user in <code>data.sqlcipher</code>; the server never uses a global key. See <a href="/FinSight/configuration/settings">Configuration</a>.</p><h2 id="_4-plan-execute-summarize" tabindex="-1">4. Plan, execute, summarize <a class="header-anchor" href="#_4-plan-execute-summarize" aria-label="Permalink to &quot;4. Plan, execute, summarize&quot;">​</a></h2><ol><li><strong>Plan</strong> — <code>planner::plan</code> parses the LLM JSON into a <code>PlanResult</code> (title, steps, tool calls) and persists it.</li><li><strong>Execute</strong> — <code>executor</code> runs each step via <code>ApiState</code> handlers; finance tools run against <code>finsight-core</code> and return typed results.</li><li><strong>Summarize</strong> — the agent re-calls the provider with tool results to narrate the outcome, citing figures and caveats.</li></ol><p>Post-execution the Copilot shows an action bundle with per-step status and undo guidance where applicable. Raw reasoning blocks are collapsible; everything streams and can be cancelled.</p><h2 id="deterministic-finance" tabindex="-1">Deterministic finance <a class="header-anchor" href="#deterministic-finance" aria-label="Permalink to &quot;Deterministic finance&quot;">​</a></h2><p>Tools like <code>forecast</code>, <code>cashflow</code>, and month-close are <strong>not</strong> LLM math — they are Rust functions in <code>finsight-core</code>. The model writes the story; the ledger writes the numbers.</p><p>Next: <a href="/FinSight/copilot/plans">Plans &amp; Actions</a>.</p>',18)])])}const m=t(r,[["render",n]]);export{u as __pageData,m as default};
